/**
 * Generates native Claude and Cursor rules and the Codex startup file.
 * Edit AGENTS.md, the scoped GitHub instructions, or the skill metadata.
 */

const fs   = require( 'node:fs' );
const path = require( 'node:path' );

const ROOT   = path.resolve( __dirname, '../..' );
const SCOPES = '.github/instructions';
const SKILLS = '.claude/skills';
const NOTICE = 'Generated by .github/scripts/sync-agent-instructions.js.';

/**
 * Reads LF-normalized source Markdown from a repository-relative path.
 *
 * @param {string} file
 * @return {string}
 */
function read( file ) {
	return fs.readFileSync( path.join( ROOT, file ), 'utf8' ).replaceAll( '\r\n', '\n' );
}

/**
 * Reads the metadata and body of a scoped instruction or skill.
 *
 * @param {string} file
 * @return {{file: string, metadata: string, body: string}}
 */
function document( file ) {

	const parsed = /^---\n([\s\S]+?)\n---\n([\s\S]*)$/.exec( read( file ) );
	if ( ! parsed || ! parsed[2].trim() )
		throw new Error( `Missing frontmatter or body in ${file}` );

	return { file, metadata: parsed[1], body: parsed[2].trimEnd() };
}

/**
 * Reads the scalar formats used here: plain, double-quoted, and folded text.
 *
 * @param {Object} source Document returned by document().
 * @param {string} key    Metadata field.
 * @return {string|undefined}
 */
function field( source, key ) {

	const match = new RegExp( `^${key}: ([^\\n]+)((?:\\n[ \\t]+[^\\n]+)*)`, 'm' ).exec( source.metadata );
	if ( ! match ) return;

	const [ , value, continuation ] = match;
	if ( value === '>-' && continuation )
		return continuation.trim().split( /\n[ \t]+/ ).join( ' ' );

	if ( continuation || value === '>-' )
		throw new Error( `Unsupported ${key} format in ${source.file}` );

	return value.startsWith( '"' ) ? JSON.parse( value ) : value;
}

/**
 * Builds each native rule from the same body and the host's own selector.
 *
 * @return {Map<string, string>} Expected files and contents.
 */
function outputs() {

	const files   = new Map();
	const routes  = [];
	const skills  = [];
	const scopes  = fs.readdirSync( path.join( ROOT, SCOPES ) ).sort();

	for ( const entry of scopes ) {
		if ( ! entry.endsWith( '.instructions.md' ) ) continue;

		const name = entry.slice( 0, -'.instructions.md'.length );
		const rule = document( `${SCOPES}/${entry}` );
		const desc = field( rule, 'description' );
		const globs = field( rule, 'applyTo' )?.split( ',' ).map( glob => glob.trim() );
		if ( ! desc || ! globs?.length || globs.some( glob => ! glob ) )
			throw new Error( `Expected description and file patterns in ${rule.file}` );

		const cursor = name === 'local' ? 'local-files' : name;
		const paths  = globs.map( glob => `  - ${JSON.stringify( glob )}` ).join( '\n' );
		files.set(
			`.cursor/rules/${cursor}.mdc`,
			`---\n# ${NOTICE}\ndescription: ${JSON.stringify( desc )}\nglobs: ${JSON.stringify( globs.join( ',' ) )}\nalwaysApply: false\n---\n${rule.body}\n`,
		);
		files.set(
			`.claude/rules/${name}.md`,
			`---\n# ${NOTICE}\npaths:\n${paths}\n---\n${rule.body}\n`,
		);
		const patterns = globs.map( glob => '`' + glob + '`' ).join( ', ' );
		routes.push( `- ${patterns} - \`${rule.file}\`` );
	}
	for ( const name of fs.readdirSync( path.join( ROOT, SKILLS ) ).sort() ) {
		const file = `${SKILLS}/${name}/SKILL.md`;
		if ( ! fs.existsSync( path.join( ROOT, file ) ) ) continue;

		const skill = document( file );
		const desc  = field( skill, 'description' );
		if ( field( skill, 'name' ) !== name || ! desc )
			throw new Error( `Expected matching skill name and description in ${file}` );

		const explicit = field( skill, 'disable-model-invocation' ) === 'true' ? 'Use only on an explicit request. ' : '';
		skills.push( `- \`${file}\` - ${explicit}${desc}` );
	}
	files.set( 'AGENTS.override.md', [
		`<!-- ${NOTICE} -->`,
		read( 'AGENTS.md' ).trimEnd(),
		'## Codex file instructions\n\nBefore working on a matching file, read all applicable instruction files below.',
		routes.join( '\n' ),
		'## Codex workflows\n\nFor a matching task, read the named skill directly.',
		skills.join( '\n' ),
	].join( '\n\n' ) + '\n' );

	return files;
}

/**
 * Finds managed rules left behind after a scope was renamed or removed.
 *
 * @param {Map<string, string>} files Expected generated output.
 * @return {string[]}
 */
function staleRules( files ) {

	const stale = [];
	for ( const directory of [ '.claude/rules', '.cursor/rules' ] ) {
		const full = path.join( ROOT, directory );
		if ( ! fs.existsSync( full ) ) continue;

		for ( const entry of fs.readdirSync( full, { withFileTypes: true } ) ) {
			const relative = `${directory}/${entry.name}`;
			if ( entry.isFile() && /\.mdc?$/.test( entry.name ) && ! files.has( relative )
				&& read( relative ).startsWith( `---\n# ${NOTICE}\n` )
			) stale.push( relative );
		}
	}

	return stale;
}

/**
 * Checks drift by default. Only --write updates the generated files.
 *
 * @param {string[]} args
 */
function main( args ) {

	const [ mode = '--check' ] = args;
	if ( args.length > 1 || ! [ '--check', '--write' ].includes( mode ) )
		throw new Error( 'Usage: node .github/scripts/sync-agent-instructions.js [--check|--write]' );

	const files = outputs();
	const stale = staleRules( files );
	if ( stale.length )
		throw new Error( `Remove stale generated rules:\n${stale.join( '\n' )}` );

	const changed = [];
	for ( const [ file, expected ] of files ) {
		const full = path.join( ROOT, file );
		if ( fs.existsSync( full ) && fs.readFileSync( full, 'utf8' ) === expected ) continue;

		changed.push( file );
		if ( mode === '--write' ) {
			fs.mkdirSync( path.dirname( full ), { recursive: true } );
			fs.writeFileSync( full, expected, 'utf8' );
		}
	}
	if ( mode === '--check' && changed.length )
		throw new Error( `Generated instructions need --write:\n${changed.join( '\n' )}` );

	console.log( `Checked ${files.size} generated instruction files.${mode === '--write' ? ` Updated ${changed.length}.` : ''}` );
}

try {
	main( process.argv.slice( 2 ) );
} catch ( error ) {
	console.error( error.message );
	process.exitCode = 1;
}
